function moveTo(item, destination, customDirStructure) {
    try {
        // node.warn({item:item,destination:destination,customDirStructure:customDirStructure})
        for (var i = 0; i < customDirStructure.length; i++) {
            var path = `${destination}/${customDirStructure[i].folderName}/${item.filename}`;
            if (customDirStructure[i].extensionsAvailable) {
                var extensions = customDirStructure[i].extensionsAvailable;
                var valid = extensions.sort().join(", ");
                //  node.warn({indexOf:extensions.indexOf(item.extension)})
                if (extensions.indexOf(item.extension) > 0) {
                    // node.warn({[path]:item})
                    move(item.path, path, function (err) {
                        if (err) {
                            node.status({ text: "error", fill: "red" });
                            node.error(err)
                        }
                    })
                }

            } else {
                move(item.path, path, function (err) {
                    if (err) {
                        node.status({ text: "error", fill: "red" });
                        node.error(err)
                    }
                })
            }
        }
    } catch (err) { node.error(err) }
}
function move(oldPath, newPath, callback) {

    fs.rename(oldPath, newPath, function (err) {
        if (err) {
            if (err.code === 'EXDEV') {
                copy();
            } else {
                callback(err);
            }
            return;
        }
        callback();
    });

    function copy() {
        var readStream = fs.createReadStream(oldPath);
        var writeStream = fs.createWriteStream(newPath);

        readStream.on('error', callback);
        writeStream.on('error', callback);

        readStream.on('close', function () {
            fs.unlink(oldPath, callback);
        });

        readStream.pipe(writeStream);
    }
}
